    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_1,'speak',17,NULL,NULL,'دوستی تو را برای فردا دعوت کرده اما ساعت را نگفته است؛ زمان قرار را بپرس.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"دوستی تو را برای فردا دعوت کرده اما ساعت را نگفته است؛ زمان قرار را بپرس.","scenario_fa":"دوستی تو را برای فردا دعوت کرده اما ساعت را نگفته است؛ زمان قرار را بپرس.","accepted":["Wann treffen wir uns morgen?","Um wie viel Uhr ist unser Termin?"],"acceptedIntents":["Wann treffen wir uns morgen?","Um wie viel Uhr ist unser Termin?"],"accepted_intents":["Wann treffen wir uns morgen?","Um wie viel Uhr ist unser Termin?"],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',12));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_1,'speak',18,NULL,NULL,'می‌خواهی ساعت قرار را تایید کنی؛ بگو فردا ساعت پنج آنجا هستی.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"می‌خواهی ساعت قرار را تایید کنی؛ بگو فردا ساعت پنج آنجا هستی.","scenario_fa":"می‌خواهی ساعت قرار را تایید کنی؛ بگو فردا ساعت پنج آنجا هستی.","accepted":["Ich bin morgen um fünf Uhr dort.","Morgen komme ich um fünf Uhr."],"acceptedIntents":["Ich bin morgen um fünf Uhr dort.","Morgen komme ich um fünf Uhr."],"accepted_intents":["Ich bin morgen um fünf Uhr dort.","Morgen komme ich um fünf Uhr."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',12));
