    INSERT INTO turns (lesson_id,character_id,sort_order,role,text,translation,difficulty,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES (v_l_2,v_c_lena,1,'character','Dein Kurs ist am Montag und am Mittwoch.','کلاس تو دوشنبه و چهارشنبه است.',1,NULL,NULL,JSON_ARRAY(JSON_OBJECT('surface','Dein','prefix','','suffix','','lemma','dein','partOfSpeech','determiner','wordId',v_w_035),JSON_OBJECT('surface','Kurs','prefix','','suffix','','lemma','Kurs','partOfSpeech','noun','wordId',v_w_009),JSON_OBJECT('surface','ist','prefix','','suffix','','lemma','sein','partOfSpeech','verb','wordId',v_w_087),JSON_OBJECT('surface','am','prefix','','suffix','','lemma','am','partOfSpeech','preposition','wordId',v_w_026),JSON_OBJECT('surface','Montag','prefix','','suffix','','lemma','Montag','partOfSpeech','noun','wordId',v_w_011),JSON_OBJECT('surface','und','prefix','','suffix','','lemma','und','partOfSpeech','conjunction','wordId',v_w_093),JSON_OBJECT('surface','am','prefix','','suffix','','lemma','am','partOfSpeech','preposition','wordId',v_w_026),JSON_OBJECT('surface','Mittwoch','prefix','','suffix','.','lemma','Mittwoch','partOfSpeech','noun','wordId',v_w_010)),'روزهای هفته با am','برای گفتن روز انجام کار از «am» پیش از نام روز استفاده می‌کنیم؛ مانند «am Mittwoch».',JSON_OBJECT('cefr','A1','focusPattern','روزهای هفته با am','surfaceTokenCount',8),JSON_OBJECT('audioRequired',TRUE,'surfaceReconstruction',TRUE,'series',12)); SET v_t_1=LAST_INSERT_ID();
    INSERT INTO turns (lesson_id,character_id,sort_order,role,text,translation,difficulty,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES (v_l_2,v_c_raha,2,'learner','Am Montag beginnt der Kurs um neun Uhr.','دوشنبه کلاس ساعت نه آغاز می‌شود.',1,'Am Montag beginnt der Kurs um neun Uhr.',JSON_ARRAY('Der Kurs beginnt montags um neun.','Am Montag bin ich um neun im Kurs.'),JSON_ARRAY(JSON_OBJECT('surface','Am','prefix','','suffix','','lemma','am','partOfSpeech','preposition','wordId',v_w_026),JSON_OBJECT('surface','Montag','prefix','','suffix','','lemma','Montag','partOfSpeech','noun','wordId',v_w_011),JSON_OBJECT('surface','beginnt','prefix','','suffix','','lemma','beginnen','partOfSpeech','verb','wordId',v_w_030),JSON_OBJECT('surface','der','prefix','','suffix','','lemma','der','partOfSpeech','article','wordId',v_w_037),JSON_OBJECT('surface','Kurs','prefix','','suffix','','lemma','Kurs','partOfSpeech','noun','wordId',v_w_009),JSON_OBJECT('surface','um','prefix','','suffix','','lemma','um','partOfSpeech','preposition','wordId',v_w_092),JSON_OBJECT('surface','neun','prefix','','suffix','','lemma','neun','partOfSpeech','numeral','wordId',v_w_075),JSON_OBJECT('surface','Uhr','prefix','','suffix','.','lemma','Uhr','partOfSpeech','noun','wordId',v_w_022)),'روزهای هفته با am','برای گفتن روز انجام کار از «am» پیش از نام روز استفاده می‌کنیم؛ مانند «am Mittwoch».',JSON_OBJECT('cefr','A1','focusPattern','روزهای هفته با am','surfaceTokenCount',8),JSON_OBJECT('audioRequired',TRUE,'surfaceReconstruction',TRUE,'series',12)); SET v_t_2=LAST_INSERT_ID();
    INSERT INTO turns (lesson_id,character_id,sort_order,role,text,translation,difficulty,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES (v_l_2,v_c_lena,3,'character','Am Dienstag hast du keinen Kurs.','سه‌شنبه کلاس نداری.',1,NULL,NULL,JSON_ARRAY(JSON_OBJECT('surface','Am','prefix','','suffix','','lemma','am','partOfSpeech','preposition','wordId',v_w_026),JSON_OBJECT('surface','Dienstag','prefix','','suffix','','lemma','Dienstag','partOfSpeech','noun','wordId',v_w_003),JSON_OBJECT('surface','hast','prefix','','suffix','','lemma','haben','partOfSpeech','verb','wordId',v_w_053),JSON_OBJECT('surface','du','prefix','','suffix','','lemma','du','partOfSpeech','pronoun','wordId',v_w_040),JSON_OBJECT('surface','keinen','prefix','','suffix','','lemma','kein','partOfSpeech','determiner','wordId',v_w_062),JSON_OBJECT('surface','Kurs','prefix','','suffix','.','lemma','Kurs','partOfSpeech','noun','wordId',v_w_009)),'روزهای هفته با am','برای گفتن روز انجام کار از «am» پیش از نام روز استفاده می‌کنیم؛ مانند «am Mittwoch».',JSON_OBJECT('cefr','A1','focusPattern','روزهای هفته با am','surfaceTokenCount',6),JSON_OBJECT('audioRequired',TRUE,'surfaceReconstruction',TRUE,'series',12)); SET v_t_3=LAST_INSERT_ID();
